import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Crimson/SeaStore Meeting 2022-05-25","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore Meeting 2022-05-25","date":"2022-05-25T00:00:00.000Z","updated":"2022-05-25T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","垃圾回收","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-05-25.md","filePath":"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-05-25.md","lastUpdated":1780459816000}'),s={name:"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-05-25.md"};function r(n,l,p,a,_,g){return t(),e("div",null,[...l[0]||(l[0]=[o("<p>会议纪要：</p><ol><li><p><strong>更新状态</strong>：</p><ul><li>团队正在努力改善错误日志机制，目前主要关注解决两个丢失的日志操作。</li></ul></li><li><p><strong>代码审查和合并准备</strong>：</p><ul><li>Scrub调度的清理工作接近完成，预计还需几天时间，完成后将进行代码审查。</li></ul></li><li><p><strong>GC（垃圾回收）开发</strong>：</p><ul><li>C*代的GC开发正在进行中，目前处于Red Pass阶段。</li></ul></li><li><p><strong>小型PR和测试</strong>：</p><ul><li>本周完成了两个小型PR，并进行了进一步测试，以探究空间回收事务与IO事务之间的冲突原因。</li><li>使用预填充数据的10GB RBD镜像进行随机写入测试，未发现空间回收与事务之间的冲突。</li><li>使用未预填充数据的Orbit镜像进行测试，冲突显著减少。</li><li>识别出之前观察到的冲突主要由LBA（逻辑块地址）处理不足引起。</li></ul></li><li><p><strong>优化工作</strong>：</p><ul><li>正在对In-Cash后台缓冲区进行优化。</li></ul></li><li><p><strong>结论</strong>：</p><ul><li>确认空间回收事务与IO事务间的冲突不再是主要问题。</li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>完善错误日志机制。</li><li>完成Scrub调度的清理工作并提交代码审查。</li><li>继续进行C*代GC的开发。</li><li>关注空间回收事务与IO事务间冲突的优化。</li><li>优化In-Cash后台缓冲区。</li></ul></li><li><p><strong>下次会议</strong>：</p><ul><li>会议内容已讨论完毕，期待下次会议。</li></ul></li></ol><p>请注意，原始字幕中可能存在一些错误或遗漏，但总结已尽可能准确地反映了会议的关键细节。</p>",3)])])}const S=i(s,[["render",r]]);export{C as __pageData,S as default};
